package com.nigson.integration.carrier;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.integration.platform.AuditWriter;
import com.nigson.integration.providers.CarrierProvider;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
/** The source owns staff approval; this scoped owner command only persists original cancellation facts. */
public final class CarrierCancellationService {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final CarrierProvider provider;private final AuditWriter audit;private final Clock clock;private final UUID generation;
 public CarrierCancellationService(JdbcTemplate jdbc,PlatformTransactionManager manager,CarrierProvider provider,AuditWriter audit,Clock clock,UUID generation){this.jdbc=jdbc;this.provider=provider;this.audit=audit;this.clock=clock;this.generation=ApiValues.uuid(generation.toString());tx=new TransactionTemplate(manager);tx.setTimeout(3);}
 public CarrierCancellationValues.Acknowledgement exchange(PrivateWorkload.Proof proof,CarrierCancellationValues.Command input,UUID key,UUID correlation){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-198")).findFirst().orElseThrow(ActorAssertion::denied);if(proof==null||proof.actor()!=null||!route.equals(proof.route())||!route.client().equals(proof.client())||proof.subject()==null||!proof.subject().matches("[A-Za-z0-9._:-]{1,100}"))throw ActorAssertion.denied();Objects.requireNonNull(input);if(!input.cancellationId().equals(key)||correlation==null||input.requestedAt().isAfter(clock.instant().plusSeconds(5)))throw ApiValues.invalid();String hash=CarrierCancellationValues.hash(input);
  return tx.execute(status->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");var existing=jdbc.queryForList("SELECT * FROM integration.carrier_cancellation WHERE source_request_id=?",input.cancellationId());if(!existing.isEmpty()){var row=existing.getFirst();if(!hash.equals(row.get("request_hash")))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);return view(row);}
   String mode=provider.mode()==ProviderHttp.Mode.TEST?"SANDBOX":provider.mode().name();if(!mode.equals(input.mode()))throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);var books=jdbc.queryForList("SELECT * FROM integration.carrier_booking WHERE shipment_id=? AND provider='FEDEX' FOR UPDATE",input.shipmentId());if(books.size()!=1)throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);var b=books.getFirst();if(!("carrier-booking:"+input.bookingRequestId()).equals(b.get("business_key"))||!input.reference().equals(b.get("tracking_number"))||!mode.equals(b.get("mode")))throw CarrierValues.rule();var jobs=jdbc.queryForList("SELECT * FROM integration.integration_job WHERE business_key=? FOR UPDATE",b.get("business_key"));if(jobs.size()!=1)throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);var j=jobs.getFirst();var cursor=EventCodec.JSON.readTree(j.get("cursor").toString());if(!"commerce".equals(j.get("owner_service"))||!"LOGISTICS_CREATE".equals(j.get("kind"))||!input.shipmentId().equals(j.get("resource_id"))||!CarrierBookingExecution.checkpoint(cursor)||!cursor.has("pieceTrackingNumbers")||!input.reference().equals(cursor.path("trackingNumber").asString())||!provider.accountFingerprint().equals(cursor.path("accountHash").asString())||!Objects.equals(b.get("request_hash"),cursor.path("requestHash").asString()))throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);
   existing=jdbc.queryForList("SELECT * FROM integration.carrier_cancellation WHERE source_request_id=? FOR UPDATE",input.cancellationId());if(!existing.isEmpty()){if(!hash.equals(existing.getFirst().get("request_hash")))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);return view(existing.getFirst());}if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM integration.carrier_cancellation WHERE booking_id=? AND state IN ('QUEUED','SUBMITTING','UNKNOWN','ACK_PENDING'))",Boolean.class,b.get("id"))))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
   UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO integration.carrier_cancellation(id,created_by,updated_by,source_request_id,booking_id,shipment_id,reference,mode,account_hash,request_hash,generation,requested_at,piece_numbers,next_attempt_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?)",id,proof.client(),proof.client(),input.cancellationId(),b.get("id"),input.shipmentId(),input.reference(),input.mode(),provider.accountFingerprint(),hash,generation,java.sql.Timestamp.from(input.requestedAt()),EventCodec.JSON.writeValueAsString(cursor.path("pieceTrackingNumbers")),java.sql.Timestamp.from(clock.instant()));audit.append(proof.client(),AuditValues.ActorKind.SERVICE,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.QUEUE,id,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("version",0),null);return view(jdbc.queryForMap("SELECT * FROM integration.carrier_cancellation WHERE id=?",id));});
 }
 private CarrierCancellationValues.Acknowledgement view(Map<String,Object> row){CarrierCancellationValues.Receipt receipt=row.get("callback_body")==null?null:CarrierCancellationValues.receipt(EventCodec.JSON.readTree(row.get("callback_body").toString()));String state=row.get("state").toString();if(!Set.of("CANCELLED","REJECTED").contains(state))state=row.get("outcome_state")==null?state.equals("QUEUED")?"QUEUED":"UNKNOWN":row.get("outcome_state").toString();return new CarrierCancellationValues.Acknowledgement((UUID)row.get("source_request_id"),(UUID)row.get("shipment_id"),state,receipt);}
}
